import json,statistics,hashlib,html
from pathlib import Path
from .setup import ROOT

def main():
 root=ROOT;folders=sorted((root/'quality').glob('*.seed0'));assert len(folders)==8
 per=[]
 for f in folders:
  t=json.loads((f/'timing_summary.json').read_text());m={n:json.loads((f/(n+'.json')).read_text())for n in ['Reference','Select']};per.append(dict(prompt=f.name,timing=t,metrics=m))
 summary={n:dict(generation_seconds=statistics.mean(p['timing'][n]for p in per))for n in ['Dense','Reference','Select']}
 for n in ['Reference','Select']:
  summary[n].update(lpips=statistics.mean(p['metrics'][n]['quality_vs_dense']['sparse_frames_only']['lpips']for p in per),weighted_keep=statistics.mean(p['metrics'][n]['weighted_keep']for p in per))
 summary['Select'].update(faster_prompts=sum(p['timing']['Select']<p['timing']['Reference']for p in per),lpips_wins=sum(p['metrics']['Select']['quality_vs_dense']['sparse_frames_only']['lpips']<p['metrics']['Reference']['quality_vs_dense']['sparse_frames_only']['lpips']for p in per))
 probes={f.name:json.loads(f.read_text())for f in root.glob('attention_*_rank*.json')};profiles={n:json.loads((root/f'profile_{n}_step3/kernel_attribution.json').read_text())for n in ['Reference','Select']};validation=json.loads((root/'select_validation.json').read_text())
 locked=json.loads((root/'parent_lock.json').read_text())
 for f,h in locked.items():assert hashlib.sha256(Path(f).read_bytes()).hexdigest()==h,f
 result=dict(summary=summary,per_prompt=per,selector_control=json.loads((root/'select_control.json').read_text()),selector_validation=validation,attention_diagnosis=json.loads((root/'attention_diagnosis.json').read_text()),attention_probes=probes,flex=json.loads((root/'flex_probe_gpu_meta.json').read_text()),profiles=profiles,protocol='8 Val videos, seed0,45 frames,480x832; LPIPS on final36 frames. Same-GPU alternating timing, extra warmup then median of3, mean over8. VAE excluded. No voting, Q64 shared masks, FP16 PV, or PV page skipping.',adopted='Opt14 network defaults to Select: associative top3/top2 reduction with one warp per independent query row. Existing Compact attention unchanged.',numerics='Within the same one-warp reduction order, masks and candidates are exact versus serial reference. Changing four warps to one changes mean/std rounding in a few rows; old-vs-new full trajectories are not promised bitwise identical. Every variant repeats exactly within the paired timing process.',limitations='One validation split and one seed. LPIPS improvement is descriptive, not evidence of a general quality improvement. Most attention sweeps used one representative long-history block and were rejected there.',parent_files_unchanged=len(locked))
 (root/'report.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
 before=summary['Reference'];after=summary['Select'];save=before['generation_seconds']-after['generation_seconds']
 lines=['Opt14：串行候选归约与 attention kernel 优化','本轮不使用投票。基线是 Opt11 Compact 的同一组参数。','已接入：Top3Route，用可结合的 top-3/top-2 归约替代逐个最小值归约。每个 query 仍独立选择。','尚未替换：attention。全部候选无稳定收益，仍使用原 Compact BF16 PV / INT8 QK 内核。','',f"完整视频：{before['generation_seconds']:.6f} → {after['generation_seconds']:.6f} 秒，缩短 {save*1000:.2f} ms（{save/before['generation_seconds']:.2%}）。",f"8条中 {after['faster_prompts']} 条更快；平均 LPIPS {before['lpips']:.6f} → {after['lpips']:.6f}（{after['lpips_wins']}/8条下降），不据此声称普遍质量改善。",f"保留率 {before['weighted_keep']:.6%} → {after['weighted_keep']:.6%}。Dense平均 {summary['Dense']['generation_seconds']:.6f} 秒，尚未超过 Dense。",'首chunk与Dense相同。每个方案4次计时/预热复跑均与同轮质量评估latent逐位一致。','',f"归约独立正确性：{validation['total']} 个案例与同warp数的串行版本 masks/rem/add 全部逐位一致，包括真实输入、ties、空候选池、全选、尾query块。",'由于warp数量变化引起mean/std归约舍入差异，部署旧版与新版少数候选/mask可能不同；已通过完整视频评估。','候选选择代表长历史样本：旧4warp约0.535ms，旧1warp0.561ms，新top3 1warp0.443ms。','完整路由代表block：2.519ms → 2.424ms。','', 'attention诊断（第24层、长历史、step3）：','有效token加权保留率13.99%，但按实际32×64 tile计算，QK/PV执行工作量为Dense的44.88%；执行乘加只有约31.17%属于有效选择。','原稀疏attention 2.212ms；Dense SDPA 2.999ms（Dense不含KV拼接，稀疏含量化、V打包、union与merge）。','主循环约1.971ms，250 registers/thread，profiler估算occupancy 13%。occupancy是诊断指标，不能直接等同吞吐率。','量化/V打包约0.143ms，union约0.034ms，merge约0.074ms。','', '已测但未采用：','- 多page宽tile、保持合并访存的双page、较小/较大query tile、预量化Q、不同split/warp/stage。','- 提前加载V、寄存器上限、显式PV累加、缩短FP32中间量生命周期。','- PyTorch2.6 FlexAttention：保持逐query mask，GPU构造正确BlockMask元数据；32-query tile约6.51ms，64-query tile约12.71ms（不是Q64共享mask）。','这些尝试没有兑现更高attention吞吐率，详细参数、误差及失败记录保留在JSON/log中。','', '范围与复现：','8条Val，seed0，45帧480×832；LPIPS仅后36帧；每条同卡交替预热+3次正式测速，先取中位数再跨视频平均，生成时间不含VAE。','新入口：migration.unified_router.opt14.network.load；默认Select；SLIMAV_OPT14=Reference可对照。','视频：index.html；全部数据：report.json。旧实验代码和权重未改动。']
 (root/'report.txt').write_text('\n'.join(lines)+'\n')
 page='<!doctype html><html lang="zh"><meta charset="utf-8"><title>Opt14 串行归约优化</title><style>body{max-width:1400px;margin:30px auto;padding:0 20px;font:16px system-ui;background:#111827;color:#eee}video{width:100%}pre{white-space:pre-wrap}article{margin:32px 0}</style><h1>Opt14：串行归约优化，不含投票</h1><pre>'+html.escape('\n'.join(lines[:10]))+'</pre><p>每个视频从左到右：Dense / 原 Compact / 新 top-3 归约。</p>'
 for p in per:page+=f"<article><h2>{p['prompt']}</h2><video controls preload='none' src='quality/{p['prompt']}/Dense_Reference_Select.mp4'></video></article>"
 (root/'index.html').write_text(page+'</html>');print('\n'.join(lines[:17]))
if __name__=='__main__':main()
